function JobCard({ job }) {
  const s = statusStyle[job.status];
  const stripe = job.status === "complete" ? COLORS.teal : job.status === "in-progress" ? COLORS.amber : COLORS.accent;
  return (
    <div className="rounded-lg overflow-hidden flex" style={{ background: COLORS.card, border: `1px solid ${COLORS.border}` }}>
      <div style={{ width: 5, background: stripe, boxShadow: `0 0 8px ${stripe}55` }} />
      <div className="flex-1 p-4">
        <div className="flex items-start justify-between mb-1.5">
          <span className="text-xs font-semibold tracking-wide" style={{ fontFamily: "'IBM Plex Mono', monospace", color: COLORS.textFaint }}>{job.id}</span>
          <span className="text-xs font-semibold px-2 py-1 rounded-full" style={{ background: s.bg, color: s.fg }}>{s.label}</span>
        </div>
        <h3 className="text-base font-semibold mb-1" style={{ color: COLORS.text }}>{job.title}</h3>
        <p className="text-sm mb-2.5" style={{ color: COLORS.textMute }}>{job.client}</p>
        <div className="flex flex-wrap gap-x-4 gap-y-1.5 text-xs" style={{ color: COLORS.textFaint }}>
          <span className="flex items-center gap-1"><MapPin size={13} /> {job.address}</span>
          <span className="flex items-center gap-1"><Clock size={13} /> {job.time}</span>
          <span className="flex items-center gap-1"><Wrench size={13} /> {job.crew}</span>
        </div>
      </div>
    </div>
  );
}

